import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
export const UPLOAD_DIR = process.env.NEXA_UPLOAD_DIR
  ? path.resolve(process.env.NEXA_UPLOAD_DIR)
  : path.resolve(__dirname, '../../uploads');
fs.mkdirSync(UPLOAD_DIR, { recursive: true });

export function storedFilePath(name) {
  // Names are generated by the server; do not trust a corrupt DB path.
  if (typeof name !== 'string' || path.basename(name) !== name) throw new Error('Invalid stored filename');
  return path.join(UPLOAD_DIR, name);
}

export function removeStoredFile(name) {
  try {
    fs.unlinkSync(storedFilePath(name));
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }
}
